from pathlib import Path
import re
C=Path('/workspace/output/glasspulse/elements')
required={'card','callout','chart-area','chart-bar','chart-donut','chart-line'}
for folder in C.iterdir():
 if folder.name in required:continue
 for p in (folder/'fixtures').glob('*.html'):
  s=p.read_text()
