  s=re.sub(r'(<(?:span|b) class="(?:tag|hl)[^\"]*")(?![^>]*data-el=)',r'\1 data-el="glasspulse-tag"',s)
  s=re.sub(r'<li>(.*?)</li>',r'<li class="item"><b class="name">\1</b></li>',s,flags=re.S)
  p.write_text(s)
